async def show(q, pats, n=10, width=150, maxper=2):
    r=json.loads(await web_search({"query":q}))
    print("==",q)
    for x in r[:n]:
        c=x.get('content','')
        for p in pats:
            for m in list(re.finditer(p,c))[:maxper]:
                print(x['url'][-45:],'|',c[max(0,m.start()-30):m.end()+width].replace('\n',' ')[:width+120])
    return r
